    <script>
        // Define your Web3Forms Access Key here.
        // Pre-wired to dynamically read from cPanel's .env file:
        window.NEXT_PUBLIC_WEB3FORMS_ACCESS_KEY = "<?php echo getenv('NEXT_PUBLIC_WEB3FORMS_ACCESS_KEY') ?: ''; ?>";

        (function() {
            var format = function() {
                var el = document.querySelector('.footer__info');
                if (el && !el.querySelector('span')) {
                    var text = el.textContent;
                    if (text.includes('·')) {
                        var parts = text.split('·').map(function(p) { return p.replace(/[\s\u00a0]+/g, ' ').trim(); });
                        if (parts.length === 3) {
                            el.innerHTML = '<span>' + parts[0] + '</span><span class="footer__info-sep"> · </span><span>' + parts[1] + '</span><span class="footer__info-sep"> · </span><span>' + parts[2] + '</span>';
                        }
                    }
                }
                var collage = document.querySelector('.collage');
                if (collage) {
                    var imgs = collage.querySelectorAll('img');
                    var img1, img3;
                    imgs.forEach(function(img) {
                        if (img.src.includes('about_1.jpg')) img1 = img;
                        if (img.src.includes('about_3.jpg')) img3 = img;
                    });
                    if (img1 && img3 && img1.getAttribute('data-swapped') !== 'true') {
                        img1.src = '/about_3.jpg';
                        img1.alt = 'Brand Endorsement Campaign';
                        img1.style.objectPosition = 'center top';
                        img3.src = '/about_1.jpg';
                        img3.alt = 'Creator Leadership';
                        img3.style.objectPosition = 'center top';
                        img1.setAttribute('data-swapped', 'true');
                        img3.setAttribute('data-swapped', 'true');
                    }
                }
                var quote = document.querySelector('.contact__quote');
                if (quote && !quote.querySelector('br')) {
                    quote.innerHTML = 'Creative and Unique.<br />Made for marketing.';
                }
                var form = document.querySelector('.contact__form');
                if (form && !form.getAttribute('data-intercepted')) {
                    form.setAttribute('data-intercepted', 'true');
                    form.addEventListener('submit', function(e) {
                        var accessKey = window.NEXT_PUBLIC_WEB3FORMS_ACCESS_KEY;
                        if (accessKey) {
                            e.preventDefault();
                            e.stopImmediatePropagation();
                            
                            var btn = form.querySelector('button[type="submit"]');
                            var origText = btn ? btn.innerHTML : '';
                            if (btn) {
                                btn.disabled = true;
                                btn.innerHTML = 'Sending...';
                            }
                            
                            var formData = new FormData(form);
                            formData.append('access_key', accessKey);
                            
                            fetch('https://api.web3forms.com/submit', {
                                method: 'POST',
                                body: formData
                            })
                            .then(function(res) { return res.json(); })
                            .then(function(data) {
                                if (data.success) {
                                    var container = document.querySelector('.contact__copy');
                                    if (container) {
                                        form.style.display = 'none';
                                        var msg = document.createElement('p');
                                        msg.className = 'contact__sent';
                                        msg.style.marginTop = '36px';
                                        msg.textContent = 'Thank you — we\'ll get back to you within 24 hours.';
                                        container.appendChild(msg);
                                    }
                                } else {
                                    alert(data.message || 'Something went wrong.');
                                    if (btn) {
                                        btn.disabled = false;
                                        btn.innerHTML = origText;
                                    }
                                }
                            })
                            .catch(function(err) {
                                alert('Failed to send message. Please check your connection.');
                                if (btn) {
                                    btn.disabled = false;
                                    btn.innerHTML = origText;
                                }
                            });
                        }
                    }, true);
                }
            };
            var observer = new MutationObserver(format);
            observer.observe(document.body, { childList: true, subtree: true });
            format();
        })();
    </script>
